import {all} from "vy/database";
import {escapeHTML as E,toast} from "vy/ui";
import * as G from "vy/v23-engine";
import {hasActive} from "vy/v22-start";
import {t as T,getLang as gL} from "vy/i18n";
const IMG={"sug": "data:image/webp;base64,", "ath": "data:image/webp;base64,", "logo": "data:image/webp;base64,", "cal": "data:image/webp;base64,", "db": "data:image/webp;base64,", "sw": "data:image/webp;base64,", "quick": "data:image/webp;base64,", "feat": "data:image/webp;base64,", "ph_full": "data:image/webp;base64,", "ic_full": "data:image/webp;base64,", "ph_strength": "data:image/webp;base64,", "ic_strength": "data:image/webp;base64,", "ph_endurance": "data:image/webp;base64,", "ic_endurance": "data:image/webp;base64,", "ph_speed": "data:image/webp;base64,", "ic_speed": "data:image/webp;base64,", "ph_intensity": "data:image/webp;base64,", "ic_intensity": "data:image/webp;base64,", "ph_flex": "data:image/webp;base64,", "ic_flex": "data:image/webp;base64,", "hlg": "data:image/webp;base64,", "hdb": "data:image/webp;base64,", "emb": "data:image/webp;base64,", "tro": "data:image/webp;base64,", "dmb": "data:image/webp;base64,"};
const IC={star:'<polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>',play:'<polygon points="6 3 20 12 6 21 6 3"/>',chev:'<path d="m15 18-6-6 6-6"/>',trophy:'<path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/>',target:'<circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',bars:'<line x1="12" x2="12" y1="20" y2="10"/><line x1="18" x2="18" y1="20" y2="4"/><line x1="6" x2="6" y1="20" y2="16"/>',clock:'<circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>',zap:'<path d="M4 14a1 1 0 0 1-.78-1.63l9.9-10.2a.5.5 0 0 1 .86.46l-1.92 6.02A1 1 0 0 0 13 10h7a1 1 0 0 1 .78 1.63l-9.9 10.2a.5.5 0 0 1-.86-.46l1.92-6.02A1 1 0 0 0 11 14z"/>',tpl:'<rect width="7" height="7" x="3" y="3" rx="1"/><rect width="7" height="7" x="3" y="14" rx="1"/><path d="M14 4h7"/><path d="M14 9h7"/><path d="M14 15h7"/><path d="M14 20h7"/>',redo:'<path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/>'};const ic=(n,c="wc-ic")=>`<svg class="${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${IC[n]}</svg>`;
const LV={beginner:"مبتدئ",intermediate:"متوسط",advanced:"متقدم",pro:"محترف"};
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const ld=()=>{try{return JSON.parse(localStorage.getItem("vyronV23"))||{}}catch{return{}}};
const fmt=(s,o)=>{try{return new Date(s+"T00:00:00").toLocaleDateString("ar",o)}catch{return s}};
function nextSlot(d){const p=d&&d.prog;if(!p)return null;const t=new Date();for(let o=0;o<14;o++){const x=new Date(t.getFullYear(),t.getMonth(),t.getDate()+o),wk=G.weekOf(p,iso(x));if(wk<1)continue;const s=G.micro(p,wk).find(m=>m.d===x.getDay()&&!m.rest);if(s)return{s,wk,date:iso(x),off:o}}return null}
function allSlots(d){const p=d&&d.prog;if(!p)return[];const wk=Math.max(1,Math.min(p.weeks,G.weekOf(p,iso(new Date()))||1));return G.micro(p,wk).filter(m=>!m.rest).map(s=>({s,wk}))}
async function data(){let w=[];try{w=await all("workouts")}catch{}const d=ld(),logs=d.logs||[];const rows=[...w.map(x=>({date:x.date,min:x.duration,name:x.name,ex:(x.exercises||[]).length,sets:(x.exercises||[]).reduce((a,e)=>a+(+e.sets||0),0)})),...logs.map(l=>{const t=G.typeOf(l.type);return{date:l.date,min:l.min,name:t?t.ar:"حصة",en:t?t.en:null,ex:new Set((l.sets||[]).map(s=>s.ex)).size,sets:(l.sets||[]).length}})].filter(r=>r.date).sort((a,b)=>b.date.localeCompare(a.date));return{d,rows,next:nextSlot(d)}}
const LOC={ar:"ar",en:"en-GB",fr:"fr-FR"};
const fmtL=(s,o)=>{try{return new Date(s+"T00:00:00").toLocaleDateString(LOC[gL()]||"ar",o)}catch{return s}};
const relL=s=>{const k=Math.round((new Date(iso(new Date())+"T00:00:00")-new Date(s+"T00:00:00"))/864e5);return k===0?T("vx_today"):k===1?T("vx_yest"):fmtL(s,{day:"numeric",month:"short"})};
const SV={chev:'<path d="m15 18-6-6 6-6"/>',book:'<path d="M12 7v14"/><path d="M3 18a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1h-6a3 3 0 0 0-3 3 3 3 0 0 0-3-3z"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/>',shield:'<path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/><path d="m9 12 2 2 4-4"/>',cap:'<path d="M21.42 10.922a1 1 0 0 0-.019-1.838L12.83 5.18a2 2 0 0 0-1.66 0L2.6 9.08a1 1 0 0 0 0 1.832l8.57 3.908a2 2 0 0 0 1.66 0z"/><path d="M22 10v6"/><path d="M6 12.5V16a6 3 0 0 0 12 0v-3.5"/>',clip:'<rect width="8" height="4" x="8" y="2" rx="1" ry="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><path d="m9 14 2 2 4-4"/>'};
const sv=(n,c="vx-sv")=>`<svg class="${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${SV[n]}</svg>`;
const dirOf=()=>gL()==="ar"?"rtl":"ltr";
const CATS2=[["full","vx_c_full","50% 22%"],["strength","vx_c_strength","50% 30%"],["endurance","vx_c_endurance","62% 30%"],["speed","vx_c_speed","38% 30%"],["intensity","vx_c_intensity","50% 30%"],["flex","vx_c_flex","66% 40%"]];
const vDiv=()=>`<div class="vx-div" aria-hidden="true"><i></i><svg viewBox="0 0 48 34" width="34" height="24"><defs><linearGradient id="vxg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f4f6f7"/><stop offset=".55" stop-color="#8b9196"/><stop offset="1" stop-color="#00F078"/></linearGradient></defs><path d="M2 3h12l10 17L34 3h12L24 32z" fill="none" stroke="url(#vxg)" stroke-width="3" stroke-linejoin="round"/><path d="M15 3h6l3 5.2L27 3h6L24 19z" fill="url(#vxg)"/></svg><i></i></div>`;
function catsHTML(){const l=gL();return `<section class="vx vc" dir="${dirOf()}" lang="${l}" aria-labelledby="vc-t"><header class="vc-h"><h2 class="vc-t" id="vc-t">${T("vx_cats")}</h2><img class="vc-db" src="${IMG.hdb}" alt="" width="180" height="110" decoding="async" draggable="false"><img class="vc-lg" src="${IMG.hlg}" alt="VYRON FIT" width="400" height="82" decoding="async" draggable="false"></header><div class="vc-grid">${CATS2.map(([k,key,op],i)=>`<button type="button" class="vc-card" data-wc="cat" data-cat="${k}" style="--i:${i};--op:${op}" aria-label="${T(key)}"><img class="vc-ph" src="${IMG["ph_"+k]}" alt="" width="520" height="${k==="full"||k==="strength"||k==="endurance"?339:332}" loading="lazy" decoding="async" draggable="false"><span class="vc-bar"><img class="vc-ic" src="${IMG["ic_"+k]}" alt="" width="40" height="36" decoding="async" draggable="false"><i class="vx-sep"></i><span class="vc-lb">${T(key)}</span><span class="vc-go">${sv("chev","vx-sv vx-chev")}</span></span></button>`).join("")}</div></section>`}
function lastHTML(last){const l=gL();let st;
if(last){const nm=last.name&&last.name!=="حصة"?(l!=="ar"&&last.en?last.en:last.name):T("vx_session");const bits=[relL(last.date)];if(last.min)bits.push(last.min+" "+T("ws_min"));if(last.ex)bits.push(last.ex+" "+T("vx_ex"));if(last.sets)bits.push(last.sets+" "+T("vx_sets"));
st=`<button type="button" class="vl-st vl-has" data-wc="history" aria-label="${E(nm)} — ${T("vx_open")}"><span class="vl-ico">${sv("book")}</span><i class="vx-sep"></i><span class="vl-body"><b class="vl-nm">${E(nm)}</b><span class="vl-meta">${E(bits.join(" · "))}</span><span class="vl-chip">${T("vx_done")}</span></span><span class="vl-go">${sv("chev","vx-sv vx-chev")}</span></button>`}
else st=`<div class="vl-st vl-empty" role="status"><span class="vl-ico">${sv("book")}</span><i class="vx-sep"></i><p class="vl-msg">${T("vx_empty1")} <em>${T("vx_empty2a")}</em> ${T("vx_empty2b")}</p><i class="vx-sep"></i><span class="vl-ico vl-info">${sv("info")}</span></div>`;
return `<section class="vx vl" dir="${dirOf()}" lang="${l}" aria-labelledby="vl-t"><img class="vl-dm" src="${IMG.dmb}" alt="" width="440" height="169" loading="lazy" decoding="async" draggable="false"><header class="vl-h"><img class="vl-em" src="${IMG.emb}" alt="" width="124" height="108" decoding="async" draggable="false"><i class="vx-sep"></i><h2 class="vl-t" id="vl-t">${T("vx_last")}</h2></header>${st}<button type="button" class="vl-ac" data-wc="ach" aria-label="${T("vx_ach")} · ${T("vx_pts")} · ${T("vx_rew")}"><img class="vl-tr" src="${IMG.tro}" alt="" width="308" height="264" loading="lazy" decoding="async" draggable="false"><span class="vl-lbs"><b>${T("vx_ach")}</b><b>${T("vx_pts")}</b><b>${T("vx_rew")}</b></span><span class="vl-go vl-go2">${sv("chev","vx-sv vx-chev")}</span></button><div class="vl-lks"><button type="button" class="vl-lk" data-wc="splits">${sv("clip","vx-sv vl-lki")}<i class="vx-sep"></i><span class="vl-lkt">${T("vx_splits")}</span><span class="vl-go vl-go3">${sv("chev","vx-sv vx-chev")}</span></button><button type="button" class="vl-lk" data-wc="lib">${sv("cap","vx-sv vl-lki")}<i class="vx-sep"></i><span class="vl-lkt">${T("vx_lib")}</span><span class="vl-go vl-go3">${sv("chev","vx-sv vx-chev")}</span></button><button type="button" class="vl-lk" data-wc="rest">${sv("shield","vx-sv vl-lki")}<i class="vx-sep"></i><span class="vl-lkt">${T("vx_rest")}</span><span class="vl-go vl-go3">${sv("chev","vx-sv vx-chev")}</span></button></div></section>`}
export async function workoutCenter(){const{d,rows,next}=await data(),last=rows[0];const n=next,t=n&&G.typeOf(n.s.type);
const rel=s=>{const k=Math.round((new Date(iso(new Date())+"T00:00:00")-new Date(s+"T00:00:00"))/864e5);return k===0?"اليوم":k===1?"أمس":fmt(s,{day:"numeric",month:"short"})};
const feat=n?`<section class="wc-feat"><img class="wc-fimg" src="${IMG.feat}" alt="" width="420" height="394"><div class="wc-fc"><span class="wc-tag">${ic("star")}${T("ws_tag")}</span><h2>${E(t.ar)}</h2><small>${E(t.en)}</small><div class="wc-facts"><div><i>${ic("target")}</i><span>${T("ws_goal")}</span><b>${E(G.QN[n.s.q][0])}</b></div><div><i>${ic("bars")}</i><span>${T("ws_lvl")}</span><b>${E(LV[d.athlete&&d.athlete.level]||"—")}</b></div><div><i>${ic("clock")}</i><span>${T("ws_dur")}</span><b>${n.s.min} ${T("ws_min")}</b></div></div><button class="wc-go" data-wc="start">${ic("play")}${T("ws_go")}</button></div></section>`:`<section class="wc-sg" data-l="${gL()}" dir="${gL()==='ar'?'rtl':'ltr'}" aria-label="${T('ws_tag')}"><img class="wc-sgi" src="${IMG.sug}" alt="" width="1536" height="864" decoding="async" loading="lazy" draggable="false" onerror="this.parentNode.classList.add('wc-sf')"><span class="wc-sgb">${T("ws_tag")}</span><h2 class="wc-sgt">${T("ws_title")}</h2><p class="wc-sgd">${T("ws_desc")}</p><button class="wc-sgg" data-wc="program"><span>${T("ws_btn")}</span></button></section>`;
return `<div class="wc"><section class="wc-hero2"><span class="wc-sl" aria-hidden="true"></span><img class="wc-ath" src="${IMG.ath}" alt="" width="820" height="622" fetchpriority="high" decoding="async"><div class="wc-hv"><img class="wc-lg" src="${IMG.logo}" alt="VYRON FIT" width="324" height="233"><h1>التمارين</h1><i class="wc-ln"></i><p>تدريب ذكي ... لنتائج <em>أفضل</em></p></div></section>
<div class="wc-stats"><button class="wc-st wc-s1" data-wc="week"><span class="wc-sti"><img src="${IMG.sw}" alt="" width="264" height="232" decoding="async"></span><span class="wc-stt"><span class="wc-stl">الحصة القادمة</span><b class="wc-stv">${n?(n.off===0?"اليوم":fmt(n.date,{weekday:"long",day:"numeric",month:"short"})):"—"}</b></span><span class="wc-stc">${ic("chev")}</span></button><button class="wc-st wc-s2 wc-cnt" data-wc="history"><span class="wc-sti"><img src="${IMG.db}" alt="" width="264" height="232" decoding="async"></span><span class="wc-stt"><span class="wc-stl">عدد الحصص</span><b class="wc-stv">${rows.length}</b></span><span class="wc-stc">${ic("chev")}</span></button><button class="wc-st wc-s3" data-wc="history"><span class="wc-sti"><img src="${IMG.cal}" alt="" width="264" height="232" decoding="async"></span><span class="wc-stt"><span class="wc-stl">آخر حصة</span><b class="wc-stv">${last?rel(last.date)+(last.min?" · "+last.min+" د":""):"—"}</b></span><span class="wc-stc">${ic("chev")}</span></button></div>
${feat}<div class="wc-qs"><h3 class="wc-qt">بدء سريع</h3><img src="${IMG.quick}" alt="VYRON FIT — بدء سريع" width="1451" height="1084" decoding="async" draggable="false" onerror="this.parentNode.classList.add('wc-qf')"><button class="wc-qh wc-q1" data-wc="random" aria-label="بدء حصة عشوائية"><i>${ic("zap")}</i><span>بدء حصة عشوائية</span></button><button class="wc-qh wc-q2" data-wc="template" aria-label="اختيار قالب تدريبي"><i>${ic("tpl")}</i><span>اختيار قالب تدريبي</span></button><button class="wc-qh wc-q3" data-wc="resume" aria-label="متابعة حصة سابقة"><i>${ic("redo")}</i><span>متابعة حصة سابقة</span></button></div>
${catsHTML()}${vDiv()}${lastHTML(last)}</div>`}
export function bindWorkoutCenter(render){const go=async p=>{await render(p)};
const run=async(slot)=>{await render("v23-week");const b=document.querySelector(`[data-v23="run"][data-wk="${slot.wk}"][data-day="${slot.s.d}"]`);if(b)b.click();else toast("اختر الحصة من صفحة الأسبوع")};
document.querySelectorAll("[data-wc]").forEach(b=>b.onclick=async()=>{const a=b.dataset.wc,{d,next}=await data();
if(a==="start"){if(next)run(next)}
else if(a==="random"){const l=allSlots(d);if(!l.length){toast("أنشئ برنامجاً أولاً");return go("v23-assess")}run(l[Math.floor(Math.random()*l.length)])}
else if(a==="template"||a==="splits")go("v25-splits");else if(a==="program")go("v22-program");
else if(a==="resume"){let h=false;try{h=!!hasActive()}catch{}if(h)go("v25-active");else{toast("لا توجد حصة محفوظة لاستكمالها");go("history")}}
else if(a==="cat"||a==="lib")go("v22-library");
else if(a==="history")go("history");else if(a==="week")go("v23-week");else if(a==="ach")go("records");else if(a==="rest")go("v23-rest")})}
export const WC_CSS=`.wc{padding:0 0 110px;direction:rtl;font-family:Tajawal,system-ui,sans-serif;color:#f4f7f5;max-width:560px;margin:auto}.wc button{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}

.wc-q button,.wc-q button,.wc-rec,.wc-ach{background:linear-gradient(#151719,#0b0c0d);border:1px solid #2a3a33;border-radius:14px}
.wc-feat{position:relative;overflow:hidden;border:1.5px solid #00F078;border-radius:20px;background:linear-gradient(120deg,#060b08 40%,#0b2417);box-shadow:0 0 18px #00F07833;min-height:230px;margin-top:6px}.wc-fimg{position:absolute;left:0;bottom:0;height:100%;width:auto;max-width:55%;object-fit:cover;mask-image:linear-gradient(90deg,#000 55%,transparent)}.wc-fc{position:relative;padding:14px;max-width:62%;margin-inline-end:auto;text-align:right}.wc-tag{display:inline-block;background:#00F078;color:#02130a;font-weight:800;font-size:12px;padding:3px 10px;border-radius:8px}.wc-fc h2{margin:8px 0 0;font-size:22px}.wc-fc small{color:#858B91;font-size:14px}.wc-facts{display:flex;gap:6px;margin:12px 0}.wc-facts div{flex:1;text-align:center;font-size:11px;color:#858B91}.wc-facts b{display:block;color:#fff;font-size:12px}.wc-facts i{display:block;font-style:normal;color:#00F078}
.wc-go{width:100%;min-height:48px;border:0;border-radius:24px;background:linear-gradient(#2bff9a,#00d46a);color:#02130a!important;font-weight:800;font-size:16px}.wc-h{font-size:16px;margin:18px 4px 8px;text-align:right}.wc-q{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.wc-q button{padding:12px 6px;min-height:82px;font-size:13px;line-height:1.3}.wc-q i{display:block;font-style:normal;font-size:22px;color:#00F078;margin-bottom:4px}



/* Quick Start cinematic image (tap areas mapped to the 3 cards inside the image; ratio 1451x1084) */
.wc-qs{position:relative;margin:18px 0 0;aspect-ratio:1451/1084;border-radius:18px;overflow:hidden;background:#050505;line-height:0}.wc-qs>img{display:block;width:100%;height:100%;object-fit:contain;pointer-events:none;user-select:none;-webkit-user-select:none;-webkit-user-drag:none}.wc-qs .wc-qh{position:absolute;top:35.98%;height:47.14%;margin:0;padding:0;border:0;background:transparent;border-radius:12%/9%;touch-action:manipulation}.wc-qs .wc-q1{left:68.09%;width:28.39%}.wc-qs .wc-q2{left:36.6%;width:29.08%}.wc-qs .wc-q3{left:4.62%;width:29.77%}.wc-qs .wc-qh:focus-visible{outline:2px solid #00F078;outline-offset:-2px}.wc-qs .wc-qt,.wc-qs .wc-qh>*{position:absolute;width:1px;height:1px;margin:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}.wc-qs.wc-qf{aspect-ratio:auto;overflow:visible;background:none;line-height:normal;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.wc-qs.wc-qf>img{display:none}.wc-qs.wc-qf .wc-qt{position:static;width:auto;height:auto;clip:auto;overflow:visible;white-space:normal;grid-column:1/-1;font-size:16px;margin:0 4px;text-align:right}.wc-qs.wc-qf .wc-qh{position:static;width:auto;height:auto;min-height:82px;padding:12px 6px;font-size:13px;line-height:1.3;background:linear-gradient(#151719,#0b0c0d);border:1px solid #2a3a33;border-radius:14px}.wc-qs.wc-qf .wc-qh>*{position:static;width:auto;height:auto;clip:auto;overflow:visible;white-space:normal}.wc-qs.wc-qf .wc-qh i{display:block;font-style:normal;font-size:22px;color:#00F078;margin-bottom:4px}
/* ===== Workouts redesign: Premium Fitness Tech (#050505 / #151719 / #C5C9CC / #858B91 / #00F078 / #064D31) ===== */
.wc{--bk:#050505;--cc:#151719;--sv:#C5C9CC;--gy:#858B91;--gn:#00F078;--gd:#064D31;max-width:560px}
@media(min-width:700px){.wc{max-width:760px}}
.wc-ic{width:1.1em;height:1.1em;vertical-align:-.18em;margin-inline-end:.4em;flex:none}
.wc-tag .wc-ic{width:12px;height:12px;margin-inline-end:5px;fill:currentColor}.wc-go .wc-ic{width:18px;height:18px;fill:currentColor;vertical-align:-3px}
.wc-facts i .wc-ic{width:18px;height:18px;margin:0}.wc-ach span{display:flex;align-items:center;gap:8px}.wc-ach .wc-ic,.wc-q i .wc-ic{margin:0}.wc-q i .wc-ic{width:24px;height:24px}.wc-ach em .wc-ic{margin:0;width:18px;height:18px}
.wc-hero2{position:relative;display:flex;align-items:center;min-height:clamp(230px,62vw,330px);overflow:hidden;border-radius:22px;background:radial-gradient(90% 120% at 85% 20%,#14171a,#050505 70%);border:1px solid rgba(197,201,204,.2);box-shadow:0 16px 36px #000c,inset 0 -2px 14px -6px rgba(0,240,120,.5),inset -2px 0 12px -6px rgba(0,240,120,.35);isolation:isolate;animation:wcIn .7s cubic-bezier(.2,.7,.2,1) both}
.wc-ath{position:absolute;left:0;top:0;height:100%;width:68%;max-width:none;z-index:-1;object-fit:cover;object-position:25% 20%;-webkit-mask-image:linear-gradient(90deg,#000 62%,transparent 98%),linear-gradient(180deg,#000 82%,transparent);mask-image:linear-gradient(90deg,#000 62%,transparent 98%),linear-gradient(180deg,#000 82%,transparent);-webkit-mask-composite:source-in;mask-composite:intersect;user-select:none;pointer-events:none}
.wc-sl{position:absolute;top:14px;left:16px;width:9px;height:34px;background:var(--gn);transform:skewX(-24deg);opacity:.75;box-shadow:16px 0 0 -1px rgba(0,240,120,.55);z-index:1}
.wc-hv{position:relative;margin-inline-end:auto;align-self:stretch;width:50%;padding:14px 16px 26px 14px;text-align:right;display:flex;flex-direction:column;align-items:flex-end;justify-content:center;background:linear-gradient(270deg,rgba(5,5,5,.92) 50%,transparent)}
.wc-lg{width:clamp(78px,24vw,130px);height:auto;margin-bottom:2px;filter:drop-shadow(0 0 8px rgba(0,240,120,.22))}
.wc-hv h1{margin:0;font:800 clamp(32px,10vw,56px)/1.15 Alexandria,Tajawal,sans-serif;background:linear-gradient(180deg,#fff 5%,#C5C9CC 45%,#858B91 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 2px 3px #000)}
.wc-ln{display:block;width:100%;height:1px;margin:6px 0 8px;background:linear-gradient(90deg,transparent,var(--gn),transparent);opacity:.8;background-size:200% 100%;animation:wcSweep 5s linear infinite}
.wc-hv p{margin:0;color:var(--sv);font-size:clamp(12px,3.6vw,18px)}.wc-hv p em{font-style:normal;color:var(--gn);font-weight:700}
.wc-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:-26px 0 12px;position:relative;z-index:2}
.wc-st{position:relative;overflow:hidden;display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 6px 10px;min-height:128px;text-align:center;border-radius:18px;border:1px solid rgba(197,201,204,.24);background:linear-gradient(150deg,rgba(21,23,25,.9),rgba(5,5,5,.96));-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 12px 22px #000b,inset 0 1px 0 rgba(255,255,255,.07),inset 0 -2px 10px -4px rgba(0,240,120,.55);transition:transform .25s,border-color .25s,box-shadow .25s;animation:wcIn .6s cubic-bezier(.2,.7,.2,1) both}
.wc-s1{animation-delay:.12s}.wc-s2{animation-delay:.2s}.wc-s3{animation-delay:.28s}
.wc-st::after{content:"";position:absolute;left:10%;right:10%;bottom:0;height:2px;border-radius:2px;background:linear-gradient(90deg,transparent,var(--gn),transparent);background-size:200% 100%;animation:wcSweep 4.5s linear infinite}
.wc-sti{display:block;width:62px;height:54px;flex:none;-webkit-mask-image:radial-gradient(closest-side,#000 62%,transparent);mask-image:radial-gradient(closest-side,#000 62%,transparent)}.wc-sti img{display:block;width:100%;height:100%;object-fit:cover}
.wc-stt{display:flex;flex-direction:column;align-items:center;gap:1px}.wc-stl{font-size:12px;color:var(--sv)}.wc-stv{font-size:13px;font-weight:700;color:#fff;line-height:1.25}
.wc-cnt .wc-stv{font-size:30px;color:var(--gn);line-height:1;text-shadow:0 0 14px rgba(0,240,120,.35);font-variant-numeric:tabular-nums}
.wc-stc{position:absolute;top:8px;left:8px;display:grid;place-items:center;width:22px;height:22px;border-radius:50%;border:1px solid rgba(197,201,204,.35);color:var(--sv)}.wc-stc .wc-ic{width:13px;height:13px;margin:0}
.wc-st:active{transform:scale(.96);box-shadow:0 6px 12px #000b,inset 0 0 14px rgba(0,240,120,.25)}
@media(hover:hover){.wc-st:hover{transform:translateY(-3px);border-color:rgba(0,240,120,.55);box-shadow:0 14px 26px #000c,0 0 16px rgba(0,240,120,.18),inset 0 -2px 10px -4px rgba(0,240,120,.8)}}
.wc-st:focus-visible{outline:2px solid var(--gn);outline-offset:2px}
@media(min-width:600px){.wc-stats{gap:12px;margin-top:-34px}.wc-st{flex-direction:row-reverse;justify-content:space-between;gap:10px;min-height:110px;padding:10px 14px 10px 12px;text-align:right}.wc-stt{align-items:flex-end;flex:1}.wc-stl{font-size:14px}.wc-stv{font-size:15px}.wc-cnt .wc-stv{font-size:38px}.wc-sti{width:92px;height:84px}.wc-stc{position:static;order:-1;width:26px;height:26px}}
@keyframes wcIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes wcSweep{from{background-position:200% 0}to{background-position:-200% 0}}
.wc-feat,.wc-rec,.wc-ach{border-color:rgba(197,201,204,.2)}.wc-feat{box-shadow:0 0 14px rgba(0,240,120,.15)}.wc-rec:active,.wc-ach:active,.wc-go:active,.wc-links button:active{transform:scale(.97)}
@media(prefers-reduced-motion:reduce){.wc-hero2,.wc-st,.wc-st::after,.wc-ln{animation:none!important}.wc-st{transition:none}}

/* ===== VYRON unified design: Workout Categories + Last Session (real HTML, translatable, RTL/LTR) ===== */
section.vx{--vl:linear-gradient(145deg,#f4f6f7 0%,#7b8186 26%,#d3d7da 50%,#4d5256 74%,#b9bec2 100%);--gn:#00F078;position:relative;min-width:0;max-width:100%;margin-top:18px;font-family:Alexandria,Tajawal,system-ui,sans-serif;color:#eef1f2;line-height:1.3}
section.vx,section.vx *{box-sizing:border-box}
section.vx[dir=rtl]{direction:rtl;text-align:right}section.vx[dir=ltr]{direction:ltr;text-align:left}
section.vx[lang=fr]{hyphens:manual;-webkit-hyphens:manual}
section.vx img{display:block;user-select:none;-webkit-user-select:none;-webkit-user-drag:none}
.vx-sv{width:22px;height:22px;flex:none;filter:drop-shadow(0 1px 1px #000)}
[dir=ltr] .vx-chev{transform:scaleX(-1)}
.vx-sep{flex:none;display:block;width:1px;align-self:stretch;margin:4px 0;background:linear-gradient(transparent,rgba(197,201,204,.6),transparent)}
.vx-div{display:flex;align-items:center;gap:12px;margin:22px 6px 4px}.vx-div i{flex:1;height:1px;background:linear-gradient(90deg,transparent,rgba(197,201,204,.55),transparent)}.vx-div svg{flex:none;filter:drop-shadow(0 0 6px rgba(0,240,120,.35))}
.vx-div+section.vx{margin-top:8px}
/* --- categories header --- */
.vc-h{position:relative;display:flex;align-items:center;gap:clamp(8px,2.4vw,16px);min-height:70px;padding:10px clamp(12px,3.4vw,20px);border-radius:18px;overflow:hidden;background:linear-gradient(120deg,#0b0d0e,#111416 55%,#060707);border:1px solid rgba(197,201,204,.22);box-shadow:0 10px 22px #000b,inset 0 1px 0 rgba(255,255,255,.09);animation:wcIn .6s cubic-bezier(.2,.7,.2,1) both}
.vc-h::after{content:"";position:absolute;inset:auto 8% 0 8%;height:2px;border-radius:2px;background:linear-gradient(90deg,transparent,var(--gn),transparent);opacity:.85}
.vc-t,.vl-t{margin:0;flex:1 1 0;min-width:0;font-weight:800;font-size:clamp(18px,5.2vw,28px);line-height:1.25;text-wrap:balance;background:linear-gradient(180deg,#fff 8%,#dfe2e4 52%,#b4babf);-webkit-background-clip:text;background-clip:text;color:transparent}
@supports not (background-clip:text){.vc-t,.vl-t{color:#eef1f2;background:none}}
.vc-db{flex:none;width:clamp(48px,13vw,80px);height:auto;filter:drop-shadow(0 4px 6px #000)}
.vc-lg{flex:none;width:clamp(112px,32vw,168px);height:auto;filter:drop-shadow(0 2px 4px #000)}
@media(max-width:420px){section.vx .vc-db{display:none}}
/* --- categories grid --- */
.vc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px}
@media(min-width:600px){.vc-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}}
.vc-card{position:relative;display:block;width:100%;aspect-ratio:1/.95;padding:0;border-radius:18px;overflow:hidden;isolation:isolate;border:1.5px solid transparent;background:linear-gradient(#050606,#050606) padding-box,var(--vl) border-box;box-shadow:0 10px 20px #000a,inset 0 1px 0 rgba(255,255,255,.1);transition:transform .22s cubic-bezier(.2,.7,.2,1),box-shadow .22s;animation:wcIn .55s cubic-bezier(.2,.7,.2,1) both;animation-delay:calc(var(--i,0)*70ms + 120ms)}
@media(min-width:600px){.vc-card{aspect-ratio:1/.88}}
.vc-ph{position:absolute;inset:0;z-index:-1;width:100%;height:100%;object-fit:cover;object-position:var(--op,50% 30%);transition:transform .5s ease}
.vc-card::after{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(105deg,transparent 40%,rgba(255,255,255,.18) 50%,transparent 60%);transform:translateX(-130%);transition:transform .7s ease}
.vc-bar{position:absolute;z-index:2;inset:auto 7px 7px 7px;display:flex;align-items:center;gap:8px;min-height:46px;padding:5px 8px;border-radius:15px;border:1px solid rgba(197,201,204,.55);background:linear-gradient(180deg,rgba(24,27,29,.95),rgba(6,7,7,.98));box-shadow:0 6px 14px #000c,inset 0 1px 0 rgba(255,255,255,.14),inset 0 -2px 8px -3px rgba(0,240,120,.55)}
.vc-ic{flex:none;width:28px;height:26px;object-fit:contain}
.vc-lb{flex:1 1 0;min-width:0;font-weight:700;font-size:clamp(12.5px,3.5vw,15.5px);line-height:1.2;color:#f4f6f7;overflow-wrap:anywhere;text-wrap:balance}
.vc-go,.vl-go{flex:none;display:grid;place-items:center;width:24px;height:24px;border-radius:50%;border:1px solid rgba(197,201,204,.5);background:radial-gradient(#1b1f21,#070808);color:#e6e9eb}.vc-go .vx-sv,.vl-go .vx-sv{width:14px;height:14px}
.vc-card:active{transform:scale(.965);box-shadow:0 5px 10px #000b,0 0 0 2px rgba(0,240,120,.7),0 0 18px rgba(0,240,120,.35)}
.vc-card:focus-visible,.vl-st.vl-has:focus-visible,.vl-ac:focus-visible,.vl-lk:focus-visible{outline:2px solid var(--gn);outline-offset:2px}
@media(hover:hover){.vc-card:hover{transform:translateY(-3px);box-shadow:0 14px 26px #000c,0 0 0 1px rgba(0,240,120,.55),0 0 20px rgba(0,240,120,.22)}.vc-card:hover::after{transform:translateX(130%)}.vc-card:hover .vc-ph{transform:scale(1.05)}}
@media(min-width:600px){.vc-ic{width:34px;height:31px}.vc-bar{min-height:52px;inset:auto 9px 9px 9px;gap:10px}.vc-go{width:28px;height:28px}}
/* --- last session --- */
.vl{padding-bottom:clamp(44px,13vw,78px)}
.vl>*{position:relative;z-index:1}
.vl>.vl-dm{position:absolute;z-index:0;inset-inline-end:-3%;bottom:-4px;width:44%;max-width:300px;height:auto;opacity:.45;pointer-events:none;-webkit-mask-image:linear-gradient(180deg,#000 30%,transparent 95%),linear-gradient(90deg,transparent,#000 25%,#000 75%,transparent);-webkit-mask-composite:source-in;mask-image:linear-gradient(180deg,#000 30%,transparent 95%),linear-gradient(90deg,transparent,#000 25%,#000 75%,transparent);mask-composite:intersect}
.vl-h{display:flex;align-items:center;gap:clamp(10px,3vw,16px);min-height:64px;padding:4px 6px;animation:wcIn .6s cubic-bezier(.2,.7,.2,1) both}
.vl-em{flex:none;width:clamp(44px,12vw,58px);height:auto;filter:drop-shadow(0 3px 5px #000)}
.vl-h .vx-sep{margin:6px 0}
.vl-st,.vl-ac,.vl-lk{border:1.5px solid transparent;background:linear-gradient(180deg,#121517,#070808) padding-box,var(--vl) border-box;box-shadow:0 10px 20px #000a,inset 0 1px 0 rgba(255,255,255,.1),inset 0 -3px 12px -6px rgba(0,240,120,.5)}
.vl-st{display:flex;align-items:center;gap:clamp(10px,3vw,16px);width:100%;min-height:78px;margin-top:6px;padding:10px clamp(12px,3.4vw,20px);border-radius:26px;animation:wcIn .6s .1s cubic-bezier(.2,.7,.2,1) both}
.vl-ico{flex:none;display:grid;place-items:center;width:40px;height:40px;color:#d9dde0}.vl-ico .vx-sv{width:30px;height:30px}
.vl-msg{margin:0;flex:1 1 0;min-width:0;font-size:clamp(14px,3.9vw,17px);font-weight:500;line-height:1.65;color:#eceff0;text-wrap:balance}
.vl-msg em{font-style:normal;font-weight:800;color:var(--gn)}
.vl-body{flex:1 1 0;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:3px}
.vl-nm{font-size:clamp(16px,4.6vw,19px);font-weight:800;color:#fff;overflow-wrap:anywhere}
.vl-meta{font-size:clamp(13px,3.6vw,15px);color:#c5c9cc;font-weight:500}
.vl-chip{display:inline-block;margin-top:3px;padding:2px 10px;border-radius:999px;border:1px solid rgba(0,240,120,.6);background:rgba(0,240,120,.1);color:#00F078;font-size:12.5px;font-weight:700}
.vl-st.vl-has{cursor:pointer;transition:transform .2s,box-shadow .2s}.vl-st.vl-has:active{transform:scale(.98);box-shadow:0 0 0 2px rgba(0,240,120,.6),0 0 16px rgba(0,240,120,.3)}
.vl-go2{width:40px;height:40px;border:2px solid rgba(0,240,120,.7);box-shadow:0 0 10px rgba(0,240,120,.35)}.vl-go2 .vx-sv{width:20px;height:20px}
.vl-ac{position:relative;display:flex;align-items:center;gap:clamp(10px,3vw,16px);width:100%;min-height:92px;margin-top:12px;padding:8px clamp(12px,3.4vw,20px);border-radius:28px;overflow:hidden;cursor:pointer;transition:transform .2s,box-shadow .2s;animation:wcIn .6s .2s cubic-bezier(.2,.7,.2,1) both}
.vl-ac:active{transform:scale(.98);box-shadow:0 0 0 2px rgba(0,240,120,.6),0 0 16px rgba(0,240,120,.3)}
.vl-tr{flex:none;width:clamp(70px,21vw,100px);height:auto;margin-block:-4px;-webkit-mask-image:radial-gradient(closest-side,#000 62%,transparent 100%);mask-image:radial-gradient(closest-side,#000 62%,transparent 100%)}
.vl-lbs{flex:1 1 0;min-width:0;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:2px 14px;font-size:clamp(14px,4vw,19px);font-weight:800;line-height:1.3;color:#e9ecee}
.vl-lbs b{font-weight:800;white-space:nowrap}
@media(min-width:480px){.vl-lbs{flex-wrap:nowrap;gap:0 12px}.vl-lbs b+b::before{content:"";display:inline-block;width:7px;height:7px;margin-inline-end:12px;border-radius:50%;background:var(--gn);box-shadow:0 0 8px var(--gn);vertical-align:middle}}
.vl-lks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px}
.vl-lk{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-height:92px;padding:10px 6px;border-radius:20px;text-align:center;cursor:pointer;transition:transform .2s,box-shadow .2s;animation:wcIn .6s cubic-bezier(.2,.7,.2,1) both}
.vl-lk:nth-child(1){animation-delay:.3s}.vl-lk:nth-child(2){animation-delay:.37s}.vl-lk:nth-child(3){animation-delay:.44s}
.vl-lk .vx-sep,.vl-lk .vl-go3{display:none}
.vl-lki{width:30px;height:30px;color:#d9dde0}
.vl-lkt{min-width:0;font-size:clamp(12.5px,3.4vw,14.5px);font-weight:700;line-height:1.25;color:#f1f3f4;overflow-wrap:anywhere;text-wrap:balance}
.vl-lk:active{transform:scale(.96);box-shadow:0 0 0 2px rgba(0,240,120,.6),0 0 16px rgba(0,240,120,.3)}
@media(hover:hover){.vl-ac:hover,.vl-lk:hover,.vl-st.vl-has:hover{transform:translateY(-2px);box-shadow:0 14px 24px #000c,0 0 0 1px rgba(0,240,120,.5),0 0 18px rgba(0,240,120,.2)}}
@media(min-width:560px){.vl-lk{flex-direction:row;gap:10px;min-height:68px;padding:8px 12px;border-radius:24px;text-align:start}.vl-lk .vx-sep,.vl-lk .vl-go3{display:block}.vl-lk .vl-go3{display:grid}.vl-lkt{flex:1 1 0;font-size:14.5px}}
@media(prefers-reduced-motion:reduce){.vc-h,.vc-card,.vl-h,.vl-st,.vl-ac,.vl-lk{animation:none!important}.vc-card,.vc-card::after,.vc-ph,.vl-st,.vl-ac,.vl-lk{transition:none!important}.vc-card:hover::after{transform:translateX(-130%)}}


/* Suggested session (no program): cinematic image + live, translatable text (1536x864) */
.wc-sg{position:relative;margin-top:6px;aspect-ratio:1536/864;border-radius:20px;overflow:hidden;background:#050505;container-type:inline-size;line-height:1.3;isolation:isolate}.wc-sgi{display:block;width:100%;height:100%;object-fit:contain;pointer-events:none;user-select:none;-webkit-user-select:none;-webkit-user-drag:none}.wc-sgb,.wc-sgt,.wc-sgd,.wc-sgg{position:absolute;margin:0;box-sizing:border-box;display:flex;align-items:center}.wc-sgb{left:63.48%;top:6.37%;width:25.85%;height:9.26%}.wc-sgb{justify-content:flex-end;text-align:right;white-space:nowrap;font-size:max(9px,3.1cqw);font-weight:700;color:#e6e9eb;letter-spacing:0}.wc-sgt{left:51.43%;top:22.57%;width:47.4%;height:17.94%}.wc-sgt{justify-content:flex-start;font-size:max(15px,5.6cqw);font-weight:800;line-height:1.15;background:linear-gradient(180deg,#fff 5%,#C5C9CC 50%,#858B91 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 2px 3px #000);text-wrap:balance}.wc-sgd{left:60.03%;top:42.82%;width:34.51%;height:21.41%}.wc-sgd{justify-content:flex-start;font-size:max(9.5px,2.9cqw);font-weight:500;line-height:1.5;color:#d5d9dc;text-wrap:balance}.wc-sgg{left:59.38%;top:68.98%;width:39.84%;height:21.53%}.wc-sgg{padding:0;border:0;background:transparent;border-radius:999px;cursor:pointer;color:#fff;font-family:inherit;touch-action:manipulation}.wc-sgg>span{position:absolute;left:35.6%;width:43.3%;top:0;bottom:0;display:flex;align-items:center;justify-content:center;text-align:center;font-size:max(9px,2.9cqw);font-weight:700;line-height:1.2;pointer-events:none}.wc-sgg:active{background:rgba(0,240,120,.1)}.wc-sgg:focus-visible{outline:2px solid #00F078;outline-offset:-2px}.wc-sg[dir=rtl] .wc-sgt,.wc-sg[dir=rtl] .wc-sgd{text-align:right;justify-content:flex-start}.wc-sg[dir=ltr] .wc-sgt,.wc-sg[dir=ltr] .wc-sgd{left:60.1%;width:38.2%;text-align:left;justify-content:flex-start}.wc-sg[dir=ltr] .wc-sgd{width:34.5%}.wc-sg[data-l=en] .wc-sgb{font-size:max(8.5px,2.6cqw)}.wc-sg[data-l=fr] .wc-sgb{font-size:max(8.5px,2.9cqw)}.wc-sg[data-l=en] .wc-sgt{font-size:max(14px,4.6cqw)}.wc-sg[data-l=fr] .wc-sgt{font-size:max(13px,3.9cqw)}.wc-sg[data-l=en] .wc-sgd{font-size:max(9.5px,2.55cqw)}.wc-sg[data-l=fr] .wc-sgd{font-size:max(9px,2.3cqw)}.wc-sg[data-l=en] .wc-sgg>span{font-size:max(9px,2.5cqw)}.wc-sg[data-l=fr] .wc-sgg>span{font-size:max(8.5px,2.25cqw)}.wc-sg.wc-sf{aspect-ratio:auto;container-type:normal;padding:16px;border:1.5px solid #00F078;background:linear-gradient(120deg,#060b08 40%,#0b2417);display:block}.wc-sg.wc-sf>img{display:none}.wc-sg.wc-sf .wc-sgb,.wc-sg.wc-sf .wc-sgt,.wc-sg.wc-sf .wc-sgd,.wc-sg.wc-sf .wc-sgg{position:static;width:auto;height:auto;display:block;font-size:inherit}.wc-sg.wc-sf .wc-sgb{display:inline-block;background:#00F078;color:#02130a;padding:3px 10px;border-radius:8px;font-size:12px}.wc-sg.wc-sf .wc-sgt{margin:8px 0 0;font-size:22px}.wc-sg.wc-sf .wc-sgd{font-size:14px;color:#858B91}.wc-sg.wc-sf .wc-sgg{margin-top:12px;padding:12px 22px;background:linear-gradient(#2bff9a,#00d46a);color:#02130a}.wc-sg.wc-sf .wc-sgg>span{position:static;display:inline;font-size:15px}
`;
if(!document.getElementById("wc-css")){const s=document.createElement("style");s.id="wc-css";s.textContent=WC_CSS;document.head.appendChild(s)}
